// A command runner: argv in, [returncode, combined-output] out. Injected in
// tests; the default shells out with a timeout and never throws.
export type Runner = (cmd: string[]) => [number, string];

// A runner for commands that must talk to the user directly — `bin/generate-certs.sh`
// prompts for a sudo password to trust the cert and edit /etc/hosts, and a
// captured runner would swallow that prompt and look like a hang. Returns just
// the exit code, since the output already went to the terminal. Injected in tests.
export type InteractiveRunner = (cmd: string[]) => number;

/** A user-scope plugin the sandbox system depends on. */
export interface PluginSpec {
  name: string;
  marketplace: string;
  /** `claude plugin marketplace add` source (owner/repo[@ref]). */
  source: string;
  /** Optional plugins only: what it buys you, shown when it is absent. */
  note?: string;
}

/**
 * One line of the setup report.
 *
 * `ok` means converged/healthy. `optional` means a not-ok result must NOT fail
 * the run: the sandbox works without this, so the step renders as a warning and
 * `sandbox setup` still exits 0. Telepresence, Jira and the companion workspace
 * checkout are all things you can simply not have — a broken Homebrew or a
 * typo'd token is not a reason to call machine setup a failure.
 */
export interface Step {
  label: string;
  ok: boolean;
  detail: string;
  optional?: boolean;
}

/** Trim command output to the part worth showing, newest/most-specific first. */
function briefOutput(out: string, maxLines = 4): string {
  const lines = out
    .split("\n")
    .map((l) => l.trimEnd())
    .filter((l) => l.trim() && !/^\s*[✔✓⣾⣽⣻⢿⡿⣟⣯⣷]/.test(l)); // drop progress spinners
  if (!lines.length) return out.trim().slice(0, 200);
  return lines.slice(0, maxLines).join("; ");
}

